(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.ContinuityLesson,num=window.LinearLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function fmt(x){return String(x).replace('.','{,}');}
let grid='';for(let x=-1;x<=3;x++){const p=core.point(x,0);grid+=`<line x1="${p.x}" x2="${p.x}" y1="30" y2="310" class="${x===0?'wave-axis':'wave-grid-line'}"/><text x="${p.x}" y="332" text-anchor="middle" class="wave-grid-label">${x}</text>`;}for(let y=0;y<=6;y++){const p=core.point(0,y);grid+=`<line x1="50" x2="610" y1="${p.y}" y2="${p.y}" class="${y===0?'wave-axis':'wave-grid-line'}"/><text x="42" y="${p.y+5}" text-anchor="end" class="wave-grid-label">${y}</text>`;}$('#continuity-grid').innerHTML=grid;
function segment(x1,y1,x2,y2){const a=core.point(x1,y1),b=core.point(x2,y2);return `M${a.x} ${a.y}L${b.x} ${b.y}`;}
function draw(){const kind=$('#continuity-kind').value,k=Number($('#continuity-value').value)/2,defined=$('#point-defined').checked,t=core.inspect(kind,k,defined);$('#point-output').value=String(k).replace('.',',');$('#continuity-value').setAttribute('aria-valuetext',String(k));$('#continuity-value').disabled=!defined;$('#repair-feedback').textContent='';const rows=kind==='join'?[String.raw`x+1,&x\ne1`]:[String.raw`x+1,&x<1`,String.raw`x+3,&x>1`];if(defined)rows.push(String.raw`${fmt(k)},&x=1`);math($('#continuity-formula'),kind==='join'&&!defined?String.raw`f(x)=x+1,\quad x\ne1`:String.raw`f(x)=\begin{cases}`+rows.join(String.raw`\\`)+String.raw`\end{cases}`);$('#continuity-left').setAttribute('d',segment(-1,core.branch(kind,-1,'left'),1,t.left));$('#continuity-right').setAttribute('d',segment(1,t.right,3,core.branch(kind,3,'right')));$('#continuity-holes').innerHTML=(kind==='join'?[2]:[2,4]).map(y=>{const p=core.point(1,y);return `<circle cx="${p.x}" cy="${p.y}" r="5" class="continuity-hole"/>`;}).join('');const point=core.point(1,k);$('#continuity-point').setAttribute('cx',point.x);$('#continuity-point').setAttribute('cy',point.y);$('#continuity-point').setAttribute('visibility',defined?'visible':'hidden');math($('#continuity-limits'),String.raw`\begin{aligned}\lim_{x\to1^-}f(x)&=${t.left}\\\lim_{x\to1^+}f(x)&=${t.right}\\\lim_{x\to1}f(x)&`+(t.limit===null?String.raw`\text{ tidak ada}`:'='+t.limit)+String.raw`\\f(1)&`+(defined?'='+fmt(k):String.raw`\text{ tidak terdefinisi}`)+String.raw`\end{aligned}`);$('#test-value').textContent=defined?`Ya. Nilai di titik satu adalah ${String(k).replace('.',',')}.`:'Tidak. Nilai fungsi di titik satu belum didefinisikan.';$('#test-limit').textContent=t.limitExists?'Ya. Kedua sisi mendekati dua.':'Tidak. Kiri mendekati dua, kanan mendekati empat.';$('#test-match').textContent=t.matches?'Ya. Nilai fungsi dan limit sama-sama dua.':!t.limitExists?'Belum dapat dicocokkan: limit dua sisi tidak ada.':!defined?'Belum dapat dicocokkan: nilai fungsi di titik belum ada.':`Tidak. Limitnya dua, tetapi nilai fungsi di titik ${String(k).replace('.',',')}.`;$('#continuity-conclusion').textContent=t.continuous?'Fungsi kontinu di masukan satu: ketiga syarat terpenuhi.':t.repairable?'Fungsi belum kontinu di satu. Karena limit dua sisi ada dan bernilai dua, memasang nilai titik dua dapat memperbaiki sambungan.':'Fungsi tidak kontinu di satu. Lompatan tidak dapat diperbaiki hanya dengan mengubah nilai di satu titik; perilaku salah satu cabang perlu diubah.';$('#continuity-plot').setAttribute('aria-label',`Grafik ${kind==='join'?'dua cabang yang sama-sama menuju dua':'dua cabang dengan lompatan'}. Limit kiri ${t.left}, limit kanan ${t.right}. Nilai tepat di satu ${defined?k:'tidak terdefinisi'}. ${t.continuous?'Kontinu di satu.':t.repairable?'Belum kontinu; nilai titik dapat diperbaiki menjadi dua.':'Tidak kontinu; mengubah satu titik tidak memperbaiki lompatan.'}`);}
for(const id of ['continuity-kind','continuity-value','point-defined'])$('#'+id).addEventListener('input',draw);$('#repair-point').addEventListener('click',()=>{if($('#continuity-kind').value==='join'){$('#point-defined').checked=true;$('#continuity-value').value=4;draw();$('#repair-feedback').textContent='Nilai titik dipasang dua. Sekarang nilai fungsi cocok dengan limit dan sambungan kontinu.';}else{$('#repair-feedback').textContent='Tidak ada pilihan satu nilai titik yang menyamakan limit kiri dua dan limit kanan empat. Ubah perilaku cabangnya agar kedua sisi sepakat.';}});$('#reset-continuity').addEventListener('click',()=>{$('#continuity-kind').value='join';$('#continuity-value').value=8;$('#point-defined').checked=true;draw();});draw();
const questions=[{tex:String.raw`g(x)=\begin{cases}\dfrac{x^2-4}{x-2},&x\ne2,\\k,&x=2,\end{cases}`,prompt:'Berapa k agar fungsi kontinu di dua?',n:4,d:1,hint:'Cari limit pecahan ketika masukan mendekati dua.',why:'Untuk x bukan dua, pecahan sama dengan x ditambah dua. Limitnya empat, sehingga nilai titik perlu dipasang empat.'},{tex:String.raw`p(x)=\begin{cases}x+1,&x<1,\\mx,&x\ge1,\end{cases}`,prompt:'Berapa m agar fungsi kontinu di satu?',n:2,d:1,hint:'Limit kiri dua; limit kanan dan nilai titik sama dengan m.',why:'Ketiga informasi harus sama. Maka m harus dua.'},{tex:String.raw`f(x)=\sqrt x,\quad x\ge0`,prompt:'Berapa limit dari kanan di nol yang cocok dengan nilai fungsinya?',n:0,d:1,hint:'Akar masukan positif yang makin kecil mendekati nol.',why:'Limit kanan akar x di nol adalah nol, sama dengan f nol. Ini pemeriksaan ujung domain dari arah yang tersedia.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n,q.d));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis bilangan yang diminta, misalnya 4 atau 0.':'Belum tepat. Periksa limit kiri, limit kanan, dan nilai tepat di titik.');}));
const choices=[{tex:String.raw`\lim_{x\to1}f(x)=2,\quad f(1)=4`,prompt:'Apakah fungsi kontinu di satu?',options:[{text:'Ya, karena nilai fungsi di titik ada.'},{text:'Tidak, karena limit dan nilai fungsi berbeda.'},{text:'Ya, karena limit ada.'}],answer:1,why:'Keberadaan nilai dan limit belum cukup. Kekontinuan juga mensyaratkan keduanya sama.'},{tex:String.raw`f(x)=|x|`,prompt:'Apa yang benar di masukan nol?',options:[{text:'Kontinu, meskipun grafik mempunyai sudut tajam.'},{text:'Tidak kontinu karena setiap grafik kontinu harus mulus.'},{text:'Tidak terdefinisi karena nilai mutlak nol tidak ada.'}],answer:0,why:'Nilai fungsi nol dan limit dari kedua sisi nol. Sudut tajam tidak menghalangi kekontinuan.'},{tex:String.raw`q(x)=x^2-2,\quad x\in[1,2]`,prompt:'Apa yang dijamin oleh kekontinuan dan perubahan tanda pada kedua ujung?',options:[{text:'Tepat dua akar pada interval itu.'},{text:'Tidak ada akar karena nilai di kedua ujung bukan nol.'},{text:'Ada setidaknya satu akar di antara satu dan dua.'}],answer:2,why:'Polinomial kontinu pada seluruh interval. Nilai ujung negatif satu dan dua mengapit nol, sehingga teorema nilai antara menjamin setidaknya satu akar. Teorema itu sendiri tidak menyatakan banyaknya tepat.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}" ${o.label?'aria-label="'+o.label+'"':''}>${o.tex?'<span data-tex="'+o.tex+'"></span>':o.text}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-continuity-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-continuity-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();